##### 算法分析

代码不多，算法不难，不需要猜、动态调试

`HighTemplar::HighTemplar`

将输入`v18`存两次到入`&v23+16`和`&v23+48`，将`"327a6c4304ad5938eaf0efb6cc3e53dc"`存入到`&v23+80`

```C++
unsigned __int64 __fastcall HighTemplar::HighTemplar(DarkTemplar *a1, __int64 a2)
{
  char v3; // [rsp+17h] [rbp-19h] BYREF
  unsigned __int64 v4; // [rsp+18h] [rbp-18h]

  v4 = __readfsqword(0x28u);
  DarkTemplar::DarkTemplar(a1);
  *a1 = &off_401EA0;
  *(a1 + 3) = 0;
  std::string::basic_string(a1 + 16, a2);
  std::string::basic_string(a1 + 48, a2);
  std::allocator<char>::allocator(&v3);
  std::string::basic_string(a1 + 80, "327a6c4304ad5938eaf0efb6cc3e53dc", &v3);
  std::allocator<char>::~allocator(&v3);
  return __readfsqword(0x28u) ^ v4;
}
```

`HighTemplar::calculate`

判断`&v23+16`的长度是否是32，然后两次循环修改`&v23+16`到`&v23+16+32`的内容

```C++
bool __fastcall HighTemplar::calculate(HighTemplar *this)
{
  __int64 v1; // rax
  _BYTE *v2; // rbx
  bool result; // al
  _BYTE *v4; // rbx
  int i; // [rsp+18h] [rbp-18h]
  int j; // [rsp+1Ch] [rbp-14h]

  if ( std::string::length(this + 16) != 32 )
  {
    v1 = std::operator<<<std::char_traits<char>>(&std::cout, "Too short or too long");
    std::ostream::operator<<(v1, &std::endl<char,std::char_traits<char>>);
    exit(-1);
  }
  for ( i = 0; i <= std::string::length(this + 16); ++i )
  {
    v2 = std::string::operator[](this + 16, i);
    *v2 = (*std::string::operator[](this + 16, i) ^ 0x50) + 23;
  }
  for ( j = 0; ; ++j )
  {
    result = j <= std::string::length(this + 16);
    if ( !result )
      break;
    v4 = std::string::operator[](this + 16, j);
    *v4 = (*std::string::operator[](this + 16, j) ^ 0x13) + 11;
  }
  return result;
}
