# def decrypt(std: list[int]) -> list[int]:
#     return list(map(lambda x: (x - 11 ^ 0x13) - 23 ^ 0x50, std))

def decrypt(std: list[int]) -> list[int]:
    lenght = len(std)
    result = [0] * lenght
    for j in range(lenght):
        result[j] = (std[j] - 11) ^ 0x13

    for i in range(lenght):
        result[i] = (result[i] - 23) ^ 0x50
    return result

std = "327a6c4304ad5938eaf0efb6cc3e53dc"
std = list(map(ord, list(std)))
# print(std)
input = decrypt(std)
flag = "flag{" + "".join(map(chr, input)) + "}"
print(flag)
# flag{tMx~qdstOs~crvtwb~aOba}qddtbrtcd}
